 22: static USAGE: &'static str = "
 23: Computes basic statistics on CSV data.
 24: 
 25: Basic statistics includes mean, median, mode, standard deviation, sum, max and
 26: min values. Note that some statistics are expensive to compute, so they must
 27: be enabled explicitly. By default, the following statistics are reported for
 28: *every* column in the CSV data: mean, max, min and standard deviation. The
 29: default set of statistics corresponds to statistics that can be computed
 30: efficiently on a stream of data (i.e., constant memory).
 31: 
 32: Computing statistics on a large file can be made much faster if you create
 33: an index for it first with 'xsv index'.
 34: 
 35: Usage:
 36:     xsv stats [options] [<input>]
 37: 
 38: stats options:
 39:     -s, --select <arg>     Select a subset of columns to compute stats for.
 40:                            See 'xsv select --help' for the format details.
 41:                            This is provided here because piping 'xsv select'
 42:                            into 'xsv stats' will disable the use of indexing.
 43:     --everything           Show all statistics available.
 44:     --mode                 Show the mode.
 45:                            This requires storing all CSV data in memory.
 46:     --cardinality          Show the cardinality.
 47:                            This requires storing all CSV data in memory.
 48:     --median               Show the median.
 49:                            This requires storing all CSV data in memory.
 50:     --nulls                Include NULLs in the population size for computing
 51:                            mean and standard deviation.
 52:     -j, --jobs <arg>       The number of jobs to run in parallel.
 53:                            This works better when the given CSV data has
 54:                            an index already created. Note that a file handle
 55:                            is opened for each job.
 56:                            When set to '0', the number of jobs is set to the
 57:                            number of CPUs detected.
 58:                            [default: 0]
 59: 
 60: Common options:
 61:     -h, --help             Display this message
 62:     -o, --output <file>    Write output to <file> instead of stdout.
 63:     -n, --no-headers       When set, the first row will NOT be interpreted
 64:                            as column names. i.e., They will be included
 65:                            in statistics.
 66:     -d, --delimiter <arg>  The field delimiter for reading CSV data.
 67:                            Must be a single character. (default: ,)
 68: ";
 69: 
 70: #[derive(Clone, Deserialize)]
 71: struct Args {
 72:     arg_input: Option<String>,
 73:     flag_select: SelectColumns,
 74:     flag_everything: bool,
 75:     flag_mode: bool,
 76:     flag_cardinality: bool,
 77:     flag_median: bool,
 78:     flag_nulls: bool,
 79:     flag_jobs: usize,
 80:     flag_output: Option<String>,
 81:     flag_no_headers: bool,
 82:     flag_delimiter: Option<Delimiter>,
 83: }
 84: 
 85: pub fn run(argv: &[&str]) -> CliResult<()> {
 86:     let args: Args = util::get_args(USAGE, argv)?;
 87: 
 88:     let mut wtr = Config::new(&args.flag_output).writer()?;
 89:     let (headers, stats) = match args.rconfig().indexed()? {
 90:         None => args.sequential_stats(),
 91:         Some(idx) => {
 92:             if args.flag_jobs == 1 {
 93:                 args.sequential_stats()
 94:             } else {
 95:                 args.parallel_stats(idx)
 96:             }
 97:         }
 98:     }?;
 99:     let stats = args.stats_to_records(stats);
100: 
101:     wtr.write_record(&args.stat_headers())?;
102:     let fields = headers.iter().zip(stats.into_iter());
103:     for (i, (header, stat)) in fields.enumerate() {
104:         let header =
105:             if args.flag_no_headers {
106:                 i.to_string().into_bytes()
107:             } else {
108:                 header.to_vec()
109:             };
110:         let stat = stat.iter().map(|f| f.as_bytes());
111:         wtr.write_record(vec![&*header].into_iter().chain(stat))?;
112:     }
113:     wtr.flush()?;
114:     Ok(())
115: }
116: 
117: impl Args {
118:     fn sequential_stats(&self) -> CliResult<(csv::ByteRecord, Vec<Stats>)> {
119:         let mut rdr = self.rconfig().reader()?;
120:         let (headers, sel) = self.sel_headers(&mut rdr)?;
121:         let stats = self.compute(&sel, rdr.byte_records())?;
122:         Ok((headers, stats))
123:     }
124: 
125:     fn parallel_stats(
126:         &self,
127:         idx: Indexed<fs::File, fs::File>,
128:     ) -> CliResult<(csv::ByteRecord, Vec<Stats>)> {
129:         // N.B. This method doesn't handle the case when the number of records
130:         // is zero correctly. So we use `sequential_stats` instead.
131:         if idx.count() == 0 {
132:             return self.sequential_stats();
133:         }
134: 
135:         let mut rdr = self.rconfig().reader()?;
136:         let (headers, sel) = self.sel_headers(&mut rdr)?;
137: 
138:         let chunk_size = util::chunk_size(idx.count() as usize, self.njobs());
139:         let nchunks = util::num_of_chunks(idx.count() as usize, chunk_size);
140: 
141:         let pool = ThreadPool::new(self.njobs());
142:         let (send, recv) = chan::sync(0);
143:         for i in 0..nchunks {
144:             let (send, args, sel) = (send.clone(), self.clone(), sel.clone());
145:             pool.execute(move || {
146:                 let mut idx = args.rconfig().indexed().unwrap().unwrap();
147:                 idx.seek((i * chunk_size) as u64).unwrap();
148:                 let it = idx.byte_records().take(chunk_size);
149:                 send.send(args.compute(&sel, it).unwrap());
150:             });
151:         }
152:         drop(send);
153:         Ok((headers, merge_all(recv.iter()).unwrap_or_else(Vec::new)))
154:     }
155: 
156:     fn stats_to_records(&self, stats: Vec<Stats>) -> Vec<csv::StringRecord> {
157:         let mut records: Vec<_> = repeat(csv::StringRecord::new())
158:             .take(stats.len())
159:             .collect();
160:         let pool = ThreadPool::new(self.njobs());
161:         let mut results = vec![];
162:         for mut stat in stats.into_iter() {
163:             let (send, recv) = chan::sync(0);
164:             results.push(recv);
165:             pool.execute(move || { send.send(stat.to_record()); });
166:         }
167:         for (i, recv) in results.into_iter().enumerate() {
168:             records[i] = recv.recv().unwrap();
169:         }
170:         records
171:     }
172: 
173:     fn compute<I>(&self, sel: &Selection, it: I) -> CliResult<Vec<Stats>>
174:             where I: Iterator<Item=csv::Result<csv::ByteRecord>> {
175:         let mut stats = self.new_stats(sel.len());
176:         for row in it {
177:             let row = row?;
178:             for (i, field) in sel.select(&row).enumerate() {
179:                 stats[i].add(field);
180:             }
181:         }
182:         Ok(stats)
183:     }
184: 
185:     fn sel_headers<R: io::Read>(
186:         &self,
187:         rdr: &mut csv::Reader<R>,
188:     ) -> CliResult<(csv::ByteRecord, Selection)> {
189:         let headers = rdr.byte_headers()?.clone();
190:         let sel = self.rconfig().selection(&headers)?;
191:         Ok((csv::ByteRecord::from_iter(sel.select(&headers)), sel))
192:     }
193: 
194:     fn rconfig(&self) -> Config {
195:         Config::new(&self.arg_input)
196:             .delimiter(self.flag_delimiter)
197:             .no_headers(self.flag_no_headers)
198:             .select(self.flag_select.clone())
199:     }
200: 
201:     fn njobs(&self) -> usize {
202:         if self.flag_jobs == 0 { util::num_cpus() } else { self.flag_jobs }
203:     }
204: 
205:     fn new_stats(&self, record_len: usize) -> Vec<Stats> {
206:         repeat(Stats::new(WhichStats {
207:             include_nulls: self.flag_nulls,
208:             sum: true,
209:             range: true,
210:             dist: true,
211:             cardinality: self.flag_cardinality || self.flag_everything,
212:             median: self.flag_median || self.flag_everything,
213:             mode: self.flag_mode || self.flag_everything,
214:         })).take(record_len).collect()
215:     }
216: 
217:     fn stat_headers(&self) -> csv::StringRecord {
218:         let mut fields = vec![
219:             "field", "type", "sum", "min", "max", "min_length", "max_length",
220:             "mean", "stddev",
221:         ];
222:         let all = self.flag_everything;
223:         if self.flag_median || all { fields.push("median"); }
224:         if self.flag_mode || all { fields.push("mode"); }
225:         if self.flag_cardinality || all { fields.push("cardinality"); }
226:         csv::StringRecord::from(fields)
227:     }
228: }
